import{l,b as o,c as n,g as t}from"./chunks/framework.Du5_AGGE.js";const p=JSON.parse('{"title":"中国古代纪时考","description":"","frontmatter":{"title":"中国古代纪时考","subTitle":"纪年","author":"oasis","date":"2026-10-27T00:00:00.000Z","tags":["读书笔记"]},"headers":[],"relativePath":"articles/books/zhong-guo-gudai-ji-shi-kao/4.md","filePath":"articles/books/zhong-guo-gudai-ji-shi-kao/4.md"}'),s={name:"articles/books/zhong-guo-gudai-ji-shi-kao/4.md"};function g(r,i,a,u,e,h){return o(),n("div",null,[...i[0]||(i[0]=[t('<p>“年”在古代又称载、岁、祀。《尔雅·释天》：“载，岁也。夏曰岁，商曰祀，周曰年，唐、虞曰载。”原文“哉”即“载”。</p><p>“岁”本是一种像斧刃的器具，可以作战，也可以农作。用于农作，指收获庄稼。“岁”的周期与太阳年重合，于是用来表示“年”。</p><h2 id="君主在位年数纪年" tabindex="-1">君主在位年数纪年</h2><p>这种纪年法有几处容易混乱：</p><ul><li>通例是逾年改元，也有不按通例改元的。</li><li>年号改得勤，一年可以有好几个元。</li><li>历代年号重复较多。</li></ul><h2 id="岁星纪年与太岁纪年" tabindex="-1">岁星纪年与太岁纪年</h2><p>恒星组成二十八个星群，即二十八宿，自西向东依次为角、亢、氐、房、心、尾、箕，斗、牛、女、虚、危、室、壁，奎、娄、胃、昴、毕、觜、参，井、鬼、柳、星、张、翼、轸。再配上四方、四时、四色：</p><ul><li><strong>东方</strong><ul><li>季节：春</li><li>颜色：青</li><li>七宿：角、亢、氐、房、心、尾、箕</li></ul></li><li><strong>北方</strong><ul><li>季节：冬</li><li>颜色：黑</li><li>七宿：斗、牛、女、虚、危、室、壁</li></ul></li><li><strong>西方</strong><ul><li>季节：秋</li><li>颜色：白</li><li>七宿：奎、娄、胃、昴、毕、觜、参</li></ul></li><li><strong>南方</strong><ul><li>季节：夏</li><li>颜色：红</li><li>七宿：井、鬼、柳、星、张、翼、轸</li></ul></li></ul><p>岁星的周期并不是整整十二年。后来发现了这个差异，便改用假想的岁星来纪年，即太岁纪年。</p><ul><li><strong>岁阳</strong>：十天干的上古别名，共十个。 <ul><li><strong>甲</strong>：阏逢（yān féng）</li><li><strong>乙</strong>：旃蒙（zhān méng）</li><li><strong>丙</strong>：柔兆（róu zhào）</li><li><strong>丁</strong>：强圉（qiáng yǔ）</li><li><strong>戊</strong>：著雍（zhù yōng）</li><li><strong>己</strong>：屠维（tú wéi）</li><li><strong>庚</strong>：上章（shàng zhāng）</li><li><strong>辛</strong>：重光（chóng guāng）</li><li><strong>壬</strong>：玄黓（xuán yì）</li><li><strong>癸</strong>：昭阳（zhāo yáng）</li></ul></li><li><strong>岁阴</strong>：十二地支的上古别名，共十二个，又叫太岁名。 <ul><li><strong>子</strong>：困敦（kùn dūn）</li><li><strong>丑</strong>：赤奋若（chì fèn ruò）</li><li><strong>寅</strong>：摄提格（shè tí gé）</li><li><strong>卯</strong>：单阏（chán yān）</li><li><strong>辰</strong>：执徐（zhí xú）</li><li><strong>巳</strong>：大荒落（dà huāng luò）</li><li><strong>午</strong>：敦牂（dūn zāng）</li><li><strong>未</strong>：协洽（xié qià）</li><li><strong>申</strong>：涒滩（tūn tān）</li><li><strong>酉</strong>：作噩（zuò è）</li><li><strong>戌</strong>：阉茂（yān mào）</li><li><strong>亥</strong>：大渊献（dà yuān xiàn）</li></ul></li></ul><p>同书：<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/1.html">纪日</a>、<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/2.html">纪时刻与时辰</a>、<a href="/articles/books/zhong-guo-gudai-ji-shi-kao/3.html">纪月</a>。</p>',11)])])}const c=l(s,[["render",g]]);export{p as __pageData,c as default};
